/// the next `]`. `None` when it never closes (globset refuses the pattern,
/// and the `[` is an ordinary character here).
pub(crate) fn bracket_class_len(text: &str) -> Option<usize> {
    let mut body = text.strip_prefix('[')?;
    let mut len = 1;
