/// on Windows a separator, never part of a component). A `[` that never
/// closes inside the component opens no class there.
fn holds_glob_syntax(component: &str, windows: bool) -> bool {
    component.contains(['*', '?', '{'])
        || (!windows && component.contains('\\'))
        || component
