        // failed to land this session — shielded, whatever it holds.
        if !shield_set.is_empty() && is_shielded(&rel, &shield_set) {
            continue;
        }
        let abs = dest_root.join(&rel);
        if is_dir {
            dirs.push(abs);
        } else {
            files.push(abs);
        }
    }

    dirs.sort_by_key(|p| p.components().count());
    dirs.reverse();

    MirrorDeletionPlan { files, dirs }
}

