        fs::create_dir_all(manifest_dir.join("src")).expect("core src");
        fs::write(root.join("Cargo.toml"), b"[workspace]\n").expect("workspace manifest");
        fs::write(manifest_dir.join("src/lib.rs"), b"pub fn value() {}\n").expect("source");
        git(root, &["init", "-q"]);
