import os, pathlib, statistics, subprocess, sys, time
work = pathlib.Path(sys.argv[1])
p = work / "probe-trees/timing"
src, dst = p / "src", p / "dst"
src.mkdir(parents=True); dst.mkdir()
(src/"kept.bin").write_bytes(b"k")
bins = {"base": work/"target/base-build/release/blit", "head": work/"target/release/blit"}
env = dict(os.environ, TMPDIR=str(work/"target/tmp"), XDG_CONFIG_HOME=str(p/"xdg-config"), XDG_STATE_HOME=str(p/"xdg-state"), XDG_DATA_HOME=str(p/"xdg-data"))
def one(which, n):
    patterns = [word for i in range(n) for word in ("--exclude", f"cache{i:04d}-??.tmp")]
    start = time.perf_counter()
    r = subprocess.run([bins[which],"--config-dir",p/("config-"+which),"copy","--dry-run","--yes",*patterns,str(src)+"/",str(dst)+"/"], cwd=work, env=env,stdin=subprocess.DEVNULL, capture_output=True, timeout=60)
    if r.returncode:
        raise RuntimeError((r.returncode,r.stderr))
    return (time.perf_counter()-start)*1000
for n in [0,50,250]:
    for which in bins: one(which,n)
    results = {which: [] for which in bins}
    for ix in range(9):
